/// `RouteOut` is the callback type for routing `SecurityDefinition` messages.
pub type RouteOut = fn(msg: SecurityDefinition, session_id: SessionID) -> Result<(), MessageRejectErrorEnum>;

/// Route type returned by the `route` function.
pub type Route = (&'static str, &'static str, Box<dyn Fn(&Message, SessionID) -> Result<(), MessageRejectErrorEnum> + Send>);

/// Returns the begin string, message type, and route function for `SecurityDefinition`.
pub fn route(router: RouteOut) -> Route {
    let r = move |msg: &Message, session_id: SessionID| -> Result<(), MessageRejectErrorEnum> {
        router(SecurityDefinition::from_message(msg.clone()), session_id)
    };
    ("9", "d", Box::new(r))
}
